#!/usr/bin/env bash
# Reproducible multi-seed comparator benchmark harness for Nucleics Align.
# Builds exact pinned commits of seq-align (dc41988), ksw2 (289609b),
# WFA2-lib (v2.3.5 / cf3eb92), and SSW (a66636b), then benchmarks all tools
# on 5 independent deterministic DNA pairs per condition generated by
# benchmarks/gen_pairs.py. Reports median and min-max wall time (ms), median
# CPU time (ms, 10 ms GNU time resolution), peak RSS (MiB), and asserts
# identical optimal global scores across all global tools.
#
# Usage: bash benchmarks/compare_harness.sh [work_dir] [threads]
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
WORK="${1:-/tmp/nucleics_compare}"
THREADS="${2:-8}"
mkdir -p "$WORK/src" "$WORK/bin" "$WORK/pairs"

NW="$ROOT/bin/needleman_wunsch"
SW="$ROOT/bin/smith_waterman"
if [ ! -x "$NW" ] || [ ! -x "$SW" ]; then
  echo "Build Nucleics Align first with 'make' in $ROOT" >&2
  exit 1
fi
if [ ! -x /usr/bin/time ]; then
  echo "GNU time (/usr/bin/time) is required for CPU time and peak RSS" >&2
  exit 1
fi

SEQALIGN_REV="dc41988"
KSW2_REV="289609b"
WFA2_REV="cf3eb92"
SSW_REV="a66636b"

echo "# host: $(uname -a)"
echo "# cpu:  $(lscpu | awk -F: '/Model name/{gsub(/^ +/,"",$2); print $2; exit}')"
echo "# gcc:  $(gcc --version | head -n1)"
echo "# python: $(python3 --version)"
echo "# nucleics-align: $(git -C "$ROOT" rev-parse --short HEAD)"

# 1. Original seq-align (pinned commit dc41988)
if [ ! -d "$WORK/src/seq-align" ]; then
  git clone --recursive https://github.com/noporpoise/seq-align "$WORK/src/seq-align"
fi
git -C "$WORK/src/seq-align" checkout -q "$SEQALIGN_REV"
git -C "$WORK/src/seq-align" submodule update --init --recursive -q
if [ ! -x "$WORK/src/seq-align/bin/needleman_wunsch" ]; then
  make -C "$WORK/src/seq-align" -j4 >/dev/null
fi
echo "# seq-align: $(git -C "$WORK/src/seq-align" rev-parse --short HEAD)"

# 2. ksw2 (pinned commit 289609b; ksw_extz2_sse, exact global: w=-1, zdrop=-1, flag=0)
if [ ! -d "$WORK/src/ksw2" ]; then
  git clone https://github.com/lh3/ksw2 "$WORK/src/ksw2"
fi
git -C "$WORK/src/ksw2" checkout -q "$KSW2_REV"
echo "# ksw2: $(git -C "$WORK/src/ksw2" rev-parse --short HEAD)"

cat > "$WORK/src/run_ksw2.c" <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include "ksw2.h"

static uint8_t *read_fa_enc(FILE *f, int *out_len) {
  size_t cap = 4096, len = 0;
  uint8_t *buf = malloc(cap);
  char line[8192];
  int started = 0;
  static const uint8_t tbl[256] = {
    ['A']=0,['a']=0,['C']=1,['c']=1,['G']=2,['g']=2,['T']=3,['t']=3
  };
  while (fgets(line, sizeof(line), f)) {
    if (line[0] == '>') {
      if (started) { fseek(f, -(long)strlen(line), SEEK_CUR); break; }
      started = 1; continue;
    }
    started = 1;
    for (char *p = line; *p; p++) {
      if (*p <= ' ') continue;
      if (len + 1 > cap) { cap *= 2; buf = realloc(buf, cap); }
      buf[len++] = tbl[(unsigned char)*p];
    }
  }
  *out_len = (int)len;
  return buf;
}

int main(int argc, char **argv) {
  if (argc < 2) return 1;
  FILE *f = fopen(argv[1], "r");
  if (!f) { perror(argv[1]); return 1; }
  int la = 0, lb = 0;
  uint8_t *a = read_fa_enc(f, &la);
  uint8_t *b = read_fa_enc(f, &lb);
  fclose(f);
  int8_t mat[25];
  for (int i = 0; i < 5; i++)
    for (int j = 0; j < 5; j++)
      mat[i*5+j] = (i == j && i < 4) ? 1 : -2;
  ksw_extz_t ez;
  memset(&ez, 0, sizeof(ez));
  /* gap open = 4, gap extend = 1 => gap(n) = -(4 + n*1), matching +1/-2/-4/-1 */
  ksw_extz2_sse(NULL, la, a, lb, b, 5, mat, 4, 1, -1, -1, 0, 0, &ez);
  printf("score: %d\ncigar_len: %d\n", ez.score, ez.n_cigar);
  free(ez.cigar);
  free(a); free(b);
  return 0;
}
EOF
gcc -O3 -msse4.1 "$WORK/src/run_ksw2.c" "$WORK/src/ksw2/ksw2_extz2_sse.c" \
  -I "$WORK/src/ksw2" -o "$WORK/bin/run_ksw2"

# 3. WFA2-lib (pinned commit cf3eb92 / v2.3.5, exact high-memory & BiWFA ultralow, heuristics=none)
if [ ! -d "$WORK/src/WFA2-lib" ]; then
  git clone --branch v2.3.5 https://github.com/smarco/WFA2-lib "$WORK/src/WFA2-lib"
fi
git -C "$WORK/src/WFA2-lib" checkout -q "$WFA2_REV"
if [ ! -f "$WORK/src/WFA2-lib/lib/libwfa.a" ]; then
  make -C "$WORK/src/WFA2-lib" lib_wfa -j4 >/dev/null
fi
echo "# WFA2-lib: $(git -C "$WORK/src/WFA2-lib" rev-parse --short HEAD) (v2.3.5)"

cat > "$WORK/src/run_wfa2.c" <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "wavefront/wavefront_align.h"

static char *read_fa(FILE *f, int *out_len) {
  size_t cap = 4096, len = 0;
  char *buf = malloc(cap);
  char line[8192];
  int started = 0;
  while (fgets(line, sizeof(line), f)) {
    if (line[0] == '>') {
      if (started) { fseek(f, -(long)strlen(line), SEEK_CUR); break; }
      started = 1; continue;
    }
    started = 1;
    for (char *p = line; *p; p++) {
      if (*p <= ' ') continue;
      if (len + 2 > cap) { cap *= 2; buf = realloc(buf, cap); }
      buf[len++] = *p;
    }
  }
  buf[len] = '\0';
  *out_len = (int)len;
  return buf;
}

int main(int argc, char **argv) {
  if (argc < 3) return 1;
  int biwfa = (strcmp(argv[1], "biwfa") == 0);
  FILE *f = fopen(argv[2], "r");
  if (!f) { perror(argv[2]); return 1; }
  int la = 0, lb = 0;
  char *a = read_fa(f, &la);
  char *b = read_fa(f, &lb);
  fclose(f);

  wavefront_aligner_attr_t attr = wavefront_aligner_attr_default;
  attr.distance_metric = gap_affine;
  /* Exact match-to-penalty conversion (Eizenga & Paten 2022) for +1/-2/-4/-1:
     2*Score = (la + lb) - (6*x + 8*o + 3*g) => match=0, mismatch=6, open=8, extend=3. */
  attr.affine_penalties.match = 0;
  attr.affine_penalties.mismatch = 6;
  attr.affine_penalties.gap_opening = 8;
  attr.affine_penalties.gap_extension = 3;
  attr.memory_mode = biwfa ? wavefront_memory_ultralow : wavefront_memory_high;
  attr.heuristic.strategy = wf_heuristic_none;
  attr.alignment_scope = compute_alignment;

  wavefront_aligner_t *wf = wavefront_aligner_new(&attr);
  int st = wavefront_align(wf, a, la, b, lb);
  if (st != 0) {
    fprintf(stderr, "WFA2 failed with status %d\n", st);
    wavefront_aligner_delete(wf);
    free(a); free(b);
    return 2;
  }
  int penalty = -wf->cigar->score; /* WFA2 stores -penalty */
  int score = (la + lb - penalty) / 2;
  printf("score: %d\ncigar_len: %d\n", score, wf->cigar->end_offset - wf->cigar->begin_offset);
  wavefront_aligner_delete(wf);
  free(a); free(b);
  return 0;
}
EOF
gcc -O3 "$WORK/src/run_wfa2.c" -I "$WORK/src/WFA2-lib" "$WORK/src/WFA2-lib/lib/libwfa.a" \
  -lm -o "$WORK/bin/run_wfa2"

# 4. SSW (pinned commit a66636b, local +2/-2/-2/-1)
if [ ! -d "$WORK/src/SSW" ]; then
  git clone https://github.com/mengyao/Complete-Striped-Smith-Waterman-Library "$WORK/src/SSW"
fi
git -C "$WORK/src/SSW" checkout -q "$SSW_REV"
echo "# SSW: $(git -C "$WORK/src/SSW" rev-parse --short HEAD)"

cat > "$WORK/src/run_ssw.c" <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include "ssw.h"

static int8_t *read_fa_enc(FILE *f, int *out_len) {
  size_t cap = 4096, len = 0;
  int8_t *buf = malloc(cap);
  char line[8192];
  int started = 0;
  static const int8_t tbl[256] = {
    ['A']=0,['a']=0,['C']=1,['c']=1,['G']=2,['g']=2,['T']=3,['t']=3
  };
  while (fgets(line, sizeof(line), f)) {
    if (line[0] == '>') {
      if (started) { fseek(f, -(long)strlen(line), SEEK_CUR); break; }
      started = 1; continue;
    }
    started = 1;
    for (char *p = line; *p; p++) {
      if (*p <= ' ') continue;
      if (len + 1 > cap) { cap *= 2; buf = realloc(buf, cap); }
      buf[len++] = tbl[(unsigned char)*p];
    }
  }
  *out_len = (int)len;
  return buf;
}

int main(int argc, char **argv) {
  if (argc < 2) return 1;
  FILE *f = fopen(argv[1], "r");
  if (!f) { perror(argv[1]); return 1; }
  int la = 0, lb = 0;
  int8_t *a = read_fa_enc(f, &la);
  int8_t *b = read_fa_enc(f, &lb);
  fclose(f);
  int8_t mat[25];
  for (int i = 0; i < 5; i++)
    for (int j = 0; j < 5; j++)
      mat[i*5+j] = (i == j && i < 4) ? 2 : -2;
  /* smith_waterman default: gap(n) = -(2 + n*1) => first base -3, extend -1 */
  s_profile *prof = ssw_init(a, la, mat, 5, 2);
  s_align *res = ssw_align(prof, b, lb, 3, 1, 1, 0, 0, 15);
  printf("score: %d\nssw_flag: %u\n", res->score1, (unsigned)res->flag);
  align_destroy(res);
  init_destroy(prof);
  free(a); free(b);
  return 0;
}
EOF
gcc -O3 "$WORK/src/run_ssw.c" "$WORK/src/SSW/src/ssw.c" -I "$WORK/src/SSW/src" -lm -o "$WORK/bin/run_ssw"

# 5. Build ablation driver
gcc -O3 "$ROOT/benchmarks/ablation.c" -I "$ROOT/src" -I "$ROOT/libs" \
  -L "$ROOT/src" -L "$ROOT/libs/string_buffer" -lalign -lstrbuf -lpthread -lz \
  -o "$WORK/bin/ablation"

python3 - "$ROOT" "$WORK" "$THREADS" <<'PY'
import hashlib, os, re, statistics, subprocess, sys, time

ROOT, WORK, THREADS = sys.argv[1], sys.argv[2], sys.argv[3]
NW = os.path.join(ROOT, "bin/needleman_wunsch")
SW = os.path.join(ROOT, "bin/smith_waterman")
ORIG_NW = os.path.join(WORK, "src/seq-align/bin/needleman_wunsch")
KSW2 = os.path.join(WORK, "bin/run_ksw2")
WFA2 = os.path.join(WORK, "bin/run_wfa2")
SSW = os.path.join(WORK, "bin/run_ssw")
ABL = os.path.join(WORK, "bin/ablation")
GEN = os.path.join(ROOT, "benchmarks/gen_pairs.py")

def sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()

def run_once(cmd, require_score=True):
    t0 = time.perf_counter()
    p = subprocess.run(["/usr/bin/time", "-v"] + cmd, capture_output=True, text=True)
    dt = (time.perf_counter() - t0) * 1000.0
    if p.returncode != 0:
        raise RuntimeError(f"Failed ({p.returncode}): {cmd}\n{p.stderr[:200]}")
    m_rss = re.search(r"Maximum resident set size \(kbytes\):\s*(\d+)", p.stderr)
    m_usr = re.search(r"User time \(seconds\):\s*([\d.]+)", p.stderr)
    m_sys = re.search(r"System time \(seconds\):\s*([\d.]+)", p.stderr)
    if not m_rss or not m_usr or not m_sys:
        raise RuntimeError(f"Failed to parse GNU time output:\n{p.stderr}")
    rss = int(m_rss.group(1)) / 1024.0
    cpu = (float(m_usr.group(1)) + float(m_sys.group(1))) * 1000.0
    m_sc = re.findall(r"(?:^|\s)score:\s*(-?\d+)", p.stdout)
    if require_score and not m_sc:
        raise RuntimeError(f"Missing score in output for {cmd}:\n{p.stdout[:200]}")
    score = int(m_sc[-1]) if m_sc else None
    return dt, cpu, rss, score

SEEDS = [1, 2, 3, 4, 5]

print("\n=== ABLATION (20 kb, 5 seeds, median [min-max] ms) ===")
for div in ["1", "10"]:
    by_cfg = {}
    for seed in SEEDS:
        fa = os.path.join(WORK, "pairs", f"20k_{div}_s{seed}.fa")
        subprocess.check_call(["python3", GEN, "20000", div, str(seed), fa])
        out = subprocess.check_output([ABL, fa, THREADS], text=True)
        for line in out.strip().splitlines():
            cfg, ms, sc = line.split("\t")
            by_cfg.setdefault(cfg, []).append(float(ms))
    print(f"-- 20 kb {div}% --")
    for cfg, vals in by_cfg.items():
        print(f"  {cfg:20s}  med={statistics.median(vals):8.2f} ms  [{min(vals):7.2f} - {max(vals):7.2f}]")

print("\n=== COMPARATOR BENCHMARK (5 seeds, median [min-max] ms, median CPU ms, median RSS MiB) ===")
for length, div in [("20000", "1"), ("20000", "10"), ("20000", "rand"),
                    ("50000", "1"), ("50000", "10"), ("50000", "rand")]:
    pairs = []
    for seed in SEEDS:
        fa = os.path.join(WORK, "pairs", f"{length}_{div}_s{seed}.fa")
        subprocess.check_call(["python3", GEN, length, div, str(seed), fa])
        pairs.append(fa)

    tools = [
        ("nw_1t",    lambda fa: [NW, "--threads", "1", "--printscores", "--file", fa]),
        ("lin_1t",   lambda fa: [NW, "--threads", "1", "--linear", "--printscores", "--file", fa]),
        ("wfa_1t",   lambda fa: [NW, "--threads", "1", "--wfa", "--printscores", "--file", fa]),
        (f"nw_{THREADS}t",  lambda fa: [NW, "--threads", THREADS, "--printscores", "--file", fa]),
        (f"lin_{THREADS}t", lambda fa: [NW, "--threads", THREADS, "--linear", "--printscores", "--file", fa]),
        ("ksw2",     lambda fa: [KSW2, fa]),
        ("wfa2_hi",  lambda fa: [WFA2, "high", fa]),
        ("wfa2_bi",  lambda fa: [WFA2, "biwfa", fa]),
    ]
    if length == "20000":
        tools.insert(0, ("seqalign", lambda fa: [ORIG_NW, "--printscores", "--file", fa]))

    print(f"\n-- Global {int(length)//1000} kb {div} (seed1 sha256={sha256(pairs[0])[:16]}) --")
    ref_scores = {}
    for tname, fn in tools:
        if length == "50000" and div == "rand" and tname in ("wfa2_hi", "wfa2_bi"):
            print(f"  {tname:12s}  skipped (not run on 50kb rand)")
            continue
        walls, cpus, rsss = [], [], []
        for idx, fa in enumerate(pairs):
            if tname == "seqalign" and idx > 0:
                continue  # 1 seed for >10s baseline
            if tname == "wfa2_hi" and length == "20000" and div == "rand" and idx > 0:
                continue
            w, c, r, sc = run_once(fn(fa), require_score=True)
            if idx not in ref_scores:
                ref_scores[idx] = sc
            else:
                assert sc == ref_scores[idx], f"Score mismatch {tname} seed {idx+1}: {sc} vs {ref_scores[idx]}"
            walls.append(w); cpus.append(c); rsss.append(r)
        print(f"  {tname:12s}  wall={statistics.median(walls):8.2f} ms [{min(walls):7.2f}-{max(walls):7.2f}]  cpu={statistics.median(cpus):8.1f} ms  rss={statistics.median(rsss):7.1f} MiB")

print("\n=== LOCAL 20 kb (--maxhits 1, +2/-2/-2/-1, 5 seeds) ===")
for div in ["1", "10", "rand"]:
    pairs = [os.path.join(WORK, "pairs", f"20000_{div}_s{seed}.fa") for seed in SEEDS]
    print(f"\n-- Local 20 kb {div} --")
    sw_scores = {}
    for tname, fn in [
        ("sw_1t", lambda fa: [SW, "--threads", "1", "--maxhits", "1", "--file", fa]),
        (f"sw_{THREADS}t", lambda fa: [SW, "--threads", THREADS, "--maxhits", "1", "--file", fa]),
        ("ssw", lambda fa: [SSW, fa]),
    ]:
        walls, cpus, rsss, scores = [], [], [], []
        for idx, fa in enumerate(pairs):
            w, c, r, sc = run_once(fn(fa), require_score=(tname == "ssw"))
            if tname == "sw_1t":
                sw_scores[idx] = sc
            elif tname == f"sw_{THREADS}t":
                assert sc == sw_scores[idx], f"Local score mismatch {tname} seed {idx+1}"
            walls.append(w); cpus.append(c); rsss.append(r); scores.append(sc)
        print(f"  {tname:12s}  wall={statistics.median(walls):8.2f} ms [{min(walls):7.2f}-{max(walls):7.2f}]  cpu={statistics.median(cpus):8.1f} ms  rss={statistics.median(rsss):7.1f} MiB  scores={scores}")
PY
